package com.bankingax.task.c02;
import java.util.Map; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
/** Best-effort OCR audit: extraction failure never blocks C-02 upload/submission. */
@Service @ConditionalOnBean(JdbcTemplate.class) public class OcrPersistence { private final JdbcTemplate jdbc; private final OcrPort ocr; private final com.fasterxml.jackson.databind.ObjectMapper json; public OcrPersistence(JdbcTemplate j,OcrPort o,com.fasterxml.jackson.databind.ObjectMapper m){jdbc=j;ocr=o;json=m;}
 @Transactional public void extract(long file,long caseId,int revision,String type,String storage){try{var r=ocr.extract(new OcrPort.ExtractRequest(file,type,storage));jdbc.update("insert into document_extraction(document_file_id,case_id,revision,method,status,extracted,failure_reason) values(?,?,?,?,?,cast(? as json),?)",file,caseId,revision,r.method(),r.status(),json.writeValueAsString(r.fields()),r.failureReason());}catch(Exception e){jdbc.update("insert into document_extraction(document_file_id,case_id,revision,method,status,failure_reason) values(?,?,?,'NONE','FAILED_NEEDS_STAFF',?)",file,caseId,revision,"OCR_UNAVAILABLE");}}
 public java.util.List<java.util.Map<String,Object>> snapshot(long caseId,int revision){return jdbc.query("select e.document_file_id,e.method,e.status,e.extracted,e.failure_reason from document_extraction e join document_file f on f.id=e.document_file_id where e.case_id=? and e.revision=? and f.case_revision=? and f.is_latest=true and f.deleted_at is null order by e.id",(r,n)->{var m=new java.util.LinkedHashMap<String,Object>();m.put("documentFileId",r.getLong(1));m.put("method",r.getString(2));m.put("status",r.getString(3));m.put("extracted",r.getString(4));m.put("failureReason",r.getString(5));m.put("manualVerificationRequired",!"SUCCEEDED".equals(r.getString(3)));return m;},caseId,revision,revision);}
}
